class Solution {
    private static final long MOD = 1_000_000_007;

    public int countGoodNumbers(long n) {
        return (int) (power(5, (n + 1) / 2) * power(4, n / 2) % MOD);
    }

    private long power(long base, long e) {
        long result = 1;
        base %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) result = result * base % MOD;
            base = base * base % MOD;
            e >>= 1;
        }
        return result;
    }
}

