                int sum = (num1[i] - '0') * (num2[j] - '0') + pos[i + j + 1];
                pos[i + j + 1] = sum % 10;
                pos[i + j] += sum / 10;
            }
        string s;
        for (int d : pos) if (!s.empty() || d != 0) s += (char) ('0' + d);
        return s.empty() ? "0" : s;
    }
