class Solution:
    def multiply(self, num1: str, num2: str) -> str:
        m, n = len(num1), len(num2)
        pos = [0] * (m + n)
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                total = int(num1[i]) * int(num2[j]) + pos[i + j + 1]
                pos[i + j + 1] = total % 10
                pos[i + j] += total // 10
        s = "".join(map(str, pos)).lstrip('0')
        return s or "0"

